export function answer(question: string): number {
  const validOperations = ['plus', 'minus', 'multiplied by', 'divided by'];
  const regex = /^What is (-?\d+)( (plus|minus|multiplied by|divided by) -?\d+)+(\?)?$/;
  const match = question.match(regex);

  if (!match) {
    if (question.startsWith('What is ')) {
      throw new Error('Unsupported operation');
    }
    throw new Error('Invalid syntax');
  }

  let result = parseInt(match[1], 10);
  const operations = match[0].split(' ').slice(2, -1);

  for (let i = 0; i < operations.length; i += 2) {
    const operation = operations[i];
    const number = parseInt(operations[i + 1], 10);

    if (!validOperations.includes(operation)) {
      throw new Error('Unsupported operation');
    }

    switch (operation) {
      case 'plus':
        result += number;
        break;
      case 'minus':
        result -= number;
        break;
      case 'multiplied by':
        result *= number;
        break;
      case 'divided by':
        if (number === 0) {
          throw new Error('Division by zero');
        }
        result = Math.floor(result / number);
        break;
    }
  }

  return result;
}
