      throw new Error('Unsupported operation');
    }

    switch (operation) {
      case 'plus':
        result += number;
        break;
      case 'minus':
        result -= number;
        break;
      case 'multiplied by':
        result *= number;
        break;
      case 'divided by':
        if (number === 0) {
          throw new Error('Division by zero');
        }
        result = Math.floor(result / number);
        break;
    }
  }

  return result;
}
